import { useState, useEffect } from "react";
import "../styles/AdminDashboard.css";

const API_BASE = "http://localhost:8000";

export default function AdminDashboard() {
  const [activeTab, setActiveTab] = useState("zones");
  const [districts, setDistricts] = useState([]);
  const [zones, setZones] = useState([]);
  const [territories, setTerritories] = useState([]);
  const [salesUsers, setSalesUsers] = useState([]);
  const [statistics, setStatistics] = useState({});
  
  const [selectedDistrict, setSelectedDistrict] = useState(null);
  const [showZoneForm, setShowZoneForm] = useState(false);
  const [showDistrictForm, setShowDistrictForm] = useState(false);
  const [showActivityForm, setShowActivityForm] = useState(false);
  const [selectedZone, setSelectedZone] = useState(null);
  
  const [newDistrict, setNewDistrict] = useState({ code: "", name: "", center_lat: 0, center_lng: 0 });
  const [newZone, setNewZone] = useState({ code: "", name: "", center_lat: 0, center_lng: 0, customers: 0, orders: 0, revenue: 0 });
  const [zoneActivity, setZoneActivity] = useState({ num_customers: 0, num_orders: 0, avg_order_value: 0, total_revenue: 0 });
  
  const [algorithmResults, setAlgorithmResults] = useState(null);

  // Fetch dữ liệu
  useEffect(() => {
    fetchDistricts();
    fetchSalesUsers();
    fetchStatistics();
  }, []);

  useEffect(() => {
    if (selectedDistrict) {
      fetchZones(selectedDistrict);
      fetchTerritories(selectedDistrict);
    }
  }, [selectedDistrict]);

  const fetchDistricts = async () => {
    try {
      const res = await fetch(`${API_BASE}/districts`);
      const data = await res.json();
      setDistricts(data);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchZones = async (districtId) => {
    try {
      const res = await fetch(`${API_BASE}/zones?district_id=${districtId}`);
      const data = await res.json();
      setZones(data);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchTerritories = async (districtId) => {
    try {
      const res = await fetch(`${API_BASE}/territories?district_id=${districtId}`);
      const data = await res.json();
      setTerritories(data);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchSalesUsers = async () => {
    try {
      const res = await fetch(`${API_BASE}/users?role=sales`);
      const data = await res.json();
      setSalesUsers(data);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchStatistics = async () => {
    try {
      const res = await fetch(`${API_BASE}/admin/statistics`);
      const data = await res.json();
      setStatistics(data);
    } catch (err) {
      console.error(err);
    }
  };

  // Create functions
  const handleAddDistrict = async () => {
    if (newDistrict.code && newDistrict.name) {
      try {
        const res = await fetch(`${API_BASE}/districts`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(newDistrict),
        });
        if (res.ok) {
          fetchDistricts();
          setNewDistrict({ code: "", name: "", center_lat: 0, center_lng: 0 });
          setShowDistrictForm(false);
        }
      } catch (err) {
        console.error(err);
      }
    }
  };

  const handleAddZone = async () => {
    if (newZone.code && newZone.name && selectedDistrict) {
      try {
        const res = await fetch(`${API_BASE}/zones`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            zone_code: newZone.code,
            name: newZone.name,
            district_id: selectedDistrict,
            center_lat: parseFloat(newZone.center_lat),
            center_lng: parseFloat(newZone.center_lng),
            num_customers: parseInt(newZone.customers),
            num_orders: parseInt(newZone.orders),
            revenue: parseFloat(newZone.revenue)
          }),
        });
        if (res.ok) {
          fetchZones(selectedDistrict);
          setNewZone({ code: "", name: "", center_lat: 0, center_lng: 0, customers: 0, orders: 0, revenue: 0 });
          setShowZoneForm(false);
        }
      } catch (err) {
        console.error(err);
      }
    }
  };

  const handleAddZoneActivity = async () => {
    if (selectedZone) {
      try {
        const res = await fetch(`${API_BASE}/zones/${selectedZone}/activities`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(zoneActivity),
        });
        if (res.ok) {
          fetchZones(selectedDistrict);
          setZoneActivity({ num_customers: 0, num_orders: 0, avg_order_value: 0, total_revenue: 0 });
          setShowActivityForm(false);
          setSelectedZone(null);
        }
      } catch (err) {
        console.error(err);
      }
    }
  };

  // Algorithm functions
  const runKMeans = async () => {
    if (!selectedDistrict) return;
    try {
      const numClusters = prompt("Nhập số phân vùng:", "3");
      if (numClusters) {
        const res = await fetch(`${API_BASE}/algorithms/kmeans`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            district_id: selectedDistrict,
            num_clusters: parseInt(numClusters),
            max_iterations: 100
          }),
        });
        const data = await res.json();
        setAlgorithmResults(data);
        fetchTerritories(selectedDistrict);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const runGreedy = async () => {
    if (!selectedDistrict) return;
    try {
      const numTerritories = prompt("Nhập số phân vùng:", "3");
      if (numTerritories) {
        const res = await fetch(`${API_BASE}/algorithms/greedy`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            district_id: selectedDistrict,
            num_territories: parseInt(numTerritories),
            max_zones_per_territory: 50
          }),
        });
        const data = await res.json();
        setAlgorithmResults(data);
        fetchTerritories(selectedDistrict);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const runLocalSearch = async (territoryId) => {
    try {
      const res = await fetch(`${API_BASE}/algorithms/localsearch`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          territory_id: territoryId,
          swap_iterations: 10
        }),
      });
      const data = await res.json();
      setAlgorithmResults(data);
      fetchTerritories(selectedDistrict);
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <div className="header-content">
          <h1>Quản lý Hệ thống (Admin)</h1>
          <div className="header-info">
            <span className="user-info">👤 Admin</span>
            <button className="logout-btn">Đăng xuất</button>
          </div>
        </div>
      </header>

      <div className="dashboard-wrapper">
        <aside className="sidebar">
          <nav className="nav-menu">
            <button
              className={`nav-item ${activeTab === "dashboard" ? "active" : ""}`}
              onClick={() => setActiveTab("dashboard")}
            >
              📊 Dashboard
            </button>
            <button
              className={`nav-item ${activeTab === "managers" ? "active" : ""}`}
              onClick={() => setActiveTab("managers")}
            >
              👔 Quản lý Manager
            </button>
            <button
              className={`nav-item ${activeTab === "shippers" ? "active" : ""}`}
              onClick={() => setActiveTab("shippers")}
            >
              🚚 Quản lý Shipper
            </button>
            <button
              className={`nav-item ${activeTab === "warehouses" ? "active" : ""}`}
              onClick={() => setActiveTab("warehouses")}
            >
              📦 Quản lý Kho hàng
            </button>
            <button
              className={`nav-item ${activeTab === "users" ? "active" : ""}`}
              onClick={() => setActiveTab("users")}
            >
              👥 Quản lý Người dùng
            </button>
            <button
              className={`nav-item ${activeTab === "products" ? "active" : ""}`}
              onClick={() => setActiveTab("products")}
            >
              📊 Quản lý Hàng hóa
            </button>
            <button
              className={`nav-item ${activeTab === "map" ? "active" : ""}`}
              onClick={() => setActiveTab("map")}
            >
              🗺️ Bản đồ (Phát triển sau)
            </button>
          </nav>
        </aside>

        <main className="main-content">
          {/* Dashboard Tab */}
          {activeTab === "dashboard" && (
            <div className="content-section">
              <h2>Tổng quan Hệ thống</h2>
              <div className="stats-grid">
                <div className="stat-card">
                  <div className="stat-icon">👔</div>
                  <div className="stat-info">
                    <h3>Số Manager</h3>
                    <p className="stat-number">{managers.length}</p>
                  </div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">🚚</div>
                  <div className="stat-info">
                    <h3>Số Shipper</h3>
                    <p className="stat-number">{shippers.length}</p>
                  </div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">📦</div>
                  <div className="stat-info">
                    <h3>Số Kho hàng</h3>
                    <p className="stat-number">{warehouses.length}</p>
                  </div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">👥</div>
                  <div className="stat-info">
                    <h3>Số Người dùng</h3>
                    <p className="stat-number">{users.length}</p>
                  </div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">📦</div>
                  <div className="stat-info">
                    <h3>Số Hàng hóa</h3>
                    <p className="stat-number">{products.length}</p>
                  </div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">✅</div>
                  <div className="stat-info">
                    <h3>Shipper Online</h3>
                    <p className="stat-number">{shippers.filter(s => s.status === "Available").length}</p>
                  </div>
                </div>
              </div>

              <div className="dashboard-charts">
                <div className="chart-container">
                  <h3>Dung lượng Kho hàng</h3>
                  {warehouses.map(w => (
                    <div key={w.id} className="warehouse-usage">
                      <label>{w.name}</label>
                      <div className="progress-bar">
                        <div className="progress-fill" style={{ width: `${(w.used / w.capacity) * 100}%` }}></div>
                      </div>
                      <span>{w.used} / {w.capacity} {((w.used / w.capacity) * 100).toFixed(1)}%</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* Managers Management Tab */}
          {activeTab === "managers" && (
            <div className="content-section">
              <div className="section-header">
                <h2>Quản lý Manager Kho hàng</h2>
                <button className="btn-primary" onClick={() => setShowManagerForm(!showManagerForm)}>
                  ➕ Thêm Manager
                </button>
              </div>

              {showManagerForm && (
                <div className="form-container">
                  <h3>Thêm Manager mới</h3>
                  <input
                    type="text"
                    placeholder="Tên Manager"
                    value={newManager.name}
                    onChange={(e) => setNewManager({ ...newManager, name: e.target.value })}
                  />
                  <input
                    type="email"
                    placeholder="Email"
                    value={newManager.email}
                    onChange={(e) => setNewManager({ ...newManager, email: e.target.value })}
                  />
                  <input
                    type="text"
                    placeholder="Số điện thoại"
                    value={newManager.phone}
                    onChange={(e) => setNewManager({ ...newManager, phone: e.target.value })}
                  />
                  <select value={newManager.warehouse} onChange={(e) => setNewManager({ ...newManager, warehouse: e.target.value })}>
                    <option value="">Chọn kho hàng</option>
                    {warehouses.map(w => <option key={w.id} value={w.name}>{w.name}</option>)}
                  </select>
                  <button className="btn-success" onClick={handleAddManager}>Lưu</button>
                  <button className="btn-secondary" onClick={() => setShowManagerForm(false)}>Hủy</button>
                </div>
              )}

              <table className="data-table">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Tên</th>
                    <th>Email</th>
                    <th>Số điện thoại</th>
                    <th>Kho hàng</th>
                    <th>Trạng thái</th>
                    <th>Hành động</th>
                  </tr>
                </thead>
                <tbody>
                  {managers.map(manager => (
                    <tr key={manager.id}>
                      <td>{manager.id}</td>
                      <td>{manager.name}</td>
                      <td>{manager.email}</td>
                      <td>{manager.phone}</td>
                      <td>{manager.warehouse}</td>
                      <td><span className="status-active">{manager.status}</span></td>
                      <td>
                        <button className="btn-danger" onClick={() => handleDeleteManager(manager.id)}>Xóa</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Shippers Management Tab */}
          {activeTab === "shippers" && (
            <div className="content-section">
              <div className="section-header">
                <h2>Quản lý Shipper</h2>
                <button className="btn-primary" onClick={() => setShowShipperForm(!showShipperForm)}>
                  ➕ Thêm Shipper
                </button>
              </div>

              {showShipperForm && (
                <div className="form-container">
                  <h3>Thêm Shipper mới</h3>
                  <input
                    type="text"
                    placeholder="Tên Shipper"
                    value={newShipper.name}
                    onChange={(e) => setNewShipper({ ...newShipper, name: e.target.value })}
                  />
                  <input
                    type="email"
                    placeholder="Email"
                    value={newShipper.email}
                    onChange={(e) => setNewShipper({ ...newShipper, email: e.target.value })}
                  />
                  <input
                    type="text"
                    placeholder="Số điện thoại"
                    value={newShipper.phone}
                    onChange={(e) => setNewShipper({ ...newShipper, phone: e.target.value })}
                  />
                  <input
                    type="text"
                    placeholder="Loại phương tiện"
                    value={newShipper.vehicle}
                    onChange={(e) => setNewShipper({ ...newShipper, vehicle: e.target.value })}
                  />
                  <button className="btn-success" onClick={handleAddShipper}>Lưu</button>
                  <button className="btn-secondary" onClick={() => setShowShipperForm(false)}>Hủy</button>
                </div>
              )}

              <table className="data-table">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Tên</th>
                    <th>Email</th>
                    <th>Số điện thoại</th>
                    <th>Phương tiện</th>
                    <th>Trạng thái</th>
                    <th>Hành động</th>
                  </tr>
                </thead>
                <tbody>
                  {shippers.map(shipper => (
                    <tr key={shipper.id}>
                      <td>{shipper.id}</td>
                      <td>{shipper.name}</td>
                      <td>{shipper.email}</td>
                      <td>{shipper.phone}</td>
                      <td>{shipper.vehicle}</td>
                      <td>
                        <span className={shipper.status === "Available" ? "status-available" : "status-busy"}>
                          {shipper.status}
                        </span>
                      </td>
                      <td>
                        <button className="btn-danger" onClick={() => handleDeleteShipper(shipper.id)}>Xóa</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Warehouses Management Tab */}
          {activeTab === "warehouses" && (
            <div className="content-section">
              <div className="section-header">
                <h2>Quản lý Kho hàng</h2>
                <button className="btn-primary" onClick={() => setShowWarehouseForm(!showWarehouseForm)}>
                  ➕ Thêm Kho hàng
                </button>
              </div>

              {showWarehouseForm && (
                <div className="form-container">
                  <h3>Thêm Kho hàng mới</h3>
                  <input
                    type="text"
                    placeholder="Tên kho hàng"
                    value={newWarehouse.name}
                    onChange={(e) => setNewWarehouse({ ...newWarehouse, name: e.target.value })}
                  />
                  <input
                    type="text"
                    placeholder="Địa điểm"
                    value={newWarehouse.location}
                    onChange={(e) => setNewWarehouse({ ...newWarehouse, location: e.target.value })}
                  />
                  <input
                    type="number"
                    placeholder="Dung lượng"
                    value={newWarehouse.capacity}
                    onChange={(e) => setNewWarehouse({ ...newWarehouse, capacity: parseInt(e.target.value) })}
                  />
                  <input
                    type="text"
                    placeholder="Người quản lý"
                    value={newWarehouse.manager}
                    onChange={(e) => setNewWarehouse({ ...newWarehouse, manager: e.target.value })}
                  />
                  <button className="btn-success" onClick={handleAddWarehouse}>Lưu</button>
                  <button className="btn-secondary" onClick={() => setShowWarehouseForm(false)}>Hủy</button>
                </div>
              )}

              <table className="data-table">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Tên kho</th>
                    <th>Địa điểm</th>
                    <th>Dung lượng</th>
                    <th>Người quản lý</th>
                    <th>Sử dụng</th>
                    <th>Hành động</th>
                  </tr>
                </thead>
                <tbody>
                  {warehouses.map(warehouse => (
                    <tr key={warehouse.id}>
                      <td>{warehouse.id}</td>
                      <td>{warehouse.name}</td>
                      <td>{warehouse.location}</td>
                      <td>{warehouse.capacity}</td>
                      <td>{warehouse.manager}</td>
                      <td>
                        <div className="mini-progress">
                          <div className="mini-bar">
                            <div className="mini-fill" style={{ width: `${(warehouse.used / warehouse.capacity) * 100}%` }}></div>
                          </div>
                          <span>{((warehouse.used / warehouse.capacity) * 100).toFixed(1)}%</span>
                        </div>
                      </td>
                      <td>
                        <button className="btn-danger" onClick={() => handleDeleteWarehouse(warehouse.id)}>Xóa</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Users Management Tab */}
          {activeTab === "users" && (
            <div className="content-section">
              <div className="section-header">
                <h2>Quản lý Người dùng</h2>
                <button className="btn-primary" onClick={() => setShowUserForm(!showUserForm)}>
                  ➕ Thêm Người dùng
                </button>
              </div>

              {showUserForm && (
                <div className="form-container">
                  <h3>Thêm Người dùng mới</h3>
                  <input
                    type="text"
                    placeholder="Tên người dùng"
                    value={newUser.name}
                    onChange={(e) => setNewUser({ ...newUser, name: e.target.value })}
                  />
                  <input
                    type="email"
                    placeholder="Email"
                    value={newUser.email}
                    onChange={(e) => setNewUser({ ...newUser, email: e.target.value })}
                  />
                  <input
                    type="text"
                    placeholder="Số điện thoại"
                    value={newUser.phone}
                    onChange={(e) => setNewUser({ ...newUser, phone: e.target.value })}
                  />
                  <select value={newUser.role} onChange={(e) => setNewUser({ ...newUser, role: e.target.value })}>
                    <option>User</option>
                    <option>Admin</option>
                    <option>Manager</option>
                  </select>
                  <button className="btn-success" onClick={handleAddUser}>Lưu</button>
                  <button className="btn-secondary" onClick={() => setShowUserForm(false)}>Hủy</button>
                </div>
              )}

              <table className="data-table">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Tên</th>
                    <th>Email</th>
                    <th>Số điện thoại</th>
                    <th>Vai trò</th>
                    <th>Trạng thái</th>
                    <th>Hành động</th>
                  </tr>
                </thead>
                <tbody>
                  {users.map(user => (
                    <tr key={user.id}>
                      <td>{user.id}</td>
                      <td>{user.name}</td>
                      <td>{user.email}</td>
                      <td>{user.phone}</td>
                      <td>{user.role}</td>
                      <td><span className="status-active">{user.status}</span></td>
                      <td>
                        <button className="btn-danger" onClick={() => handleDeleteUser(user.id)}>Xóa</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Products Management Tab */}
          {activeTab === "products" && (
            <div className="content-section">
              <div className="section-header">
                <h2>Quản lý Hàng hóa</h2>
                <button className="btn-primary" onClick={() => setShowProductForm(!showProductForm)}>
                  ➕ Thêm Hàng hóa
                </button>
              </div>

              {showProductForm && (
                <div className="form-container">
                  <h3>Thêm Hàng hóa mới</h3>
                  <input
                    type="text"
                    placeholder="Tên sản phẩm"
                    value={newProduct.name}
                    onChange={(e) => setNewProduct({ ...newProduct, name: e.target.value })}
                  />
                  <input
                    type="text"
                    placeholder="Danh mục"
                    value={newProduct.category}
                    onChange={(e) => setNewProduct({ ...newProduct, category: e.target.value })}
                  />
                  <input
                    type="number"
                    placeholder="Giá"
                    value={newProduct.price}
                    onChange={(e) => setNewProduct({ ...newProduct, price: parseInt(e.target.value) })}
                  />
                  <input
                    type="number"
                    placeholder="Số lượng"
                    value={newProduct.stock}
                    onChange={(e) => setNewProduct({ ...newProduct, stock: parseInt(e.target.value) })}
                  />
                  <select value={newProduct.warehouse} onChange={(e) => setNewProduct({ ...newProduct, warehouse: e.target.value })}>
                    <option value="">Chọn kho hàng</option>
                    {warehouses.map(w => <option key={w.id} value={w.name}>{w.name}</option>)}
                  </select>
                  <button className="btn-success" onClick={handleAddProduct}>Lưu</button>
                  <button className="btn-secondary" onClick={() => setShowProductForm(false)}>Hủy</button>
                </div>
              )}

              <table className="data-table">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Tên sản phẩm</th>
                    <th>Danh mục</th>
                    <th>Giá</th>
                    <th>Số lượng</th>
                    <th>Kho hàng</th>
                    <th>Hành động</th>
                  </tr>
                </thead>
                <tbody>
                  {products.map(product => (
                    <tr key={product.id}>
                      <td>{product.id}</td>
                      <td>{product.name}</td>
                      <td>{product.category}</td>
                      <td>{product.price.toLocaleString()} ₫</td>
                      <td>{product.stock}</td>
                      <td>{product.warehouse}</td>
                      <td>
                        <button className="btn-danger" onClick={() => handleDeleteProduct(product.id)}>Xóa</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Map Tab */}
          {activeTab === "map" && (
            <div className="content-section">
              <div className="coming-soon">
                <h2>🗺️ Bản đồ Theo dõi</h2>
                <p>Chức năng này sẽ được phát triển trong phiên bản tới</p>
                <div className="map-placeholder">
                  <p>Khu vực bản đồ tương tác</p>
                </div>
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}
